def changed_paths(before, after):
    paths = set()
    _diff(before, after, "", paths)
    return sorted(paths)


def _diff(before, after, prefix, paths):
    for key in set(before) | set(after):
        path = f"{prefix}.{key}" if prefix else key
        if key not in after:
            paths.add(path)
        elif key not in before:
            paths.add(path)
        else:
            bv = before[key]
            av = after[key]
            if isinstance(bv, dict) and isinstance(av, dict):
                _diff(bv, av, path, paths)
            elif bv != av:
                paths.add(path)
