def coalesce(intervals):
    """Merge overlapping or touching half-open integer intervals [start, end).

    - Discards empty intervals (start == end).
    - Raises ValueError if start > end.
    - Returns a sorted list of tuples without mutating the input.
    """
    cleaned = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"start ({start}) > end ({end}) in interval ({start}, {end})")
        if start == end:
            continue
        cleaned.append((start, end))

    cleaned.sort()

    if not cleaned:
        return []

    merged = [list(cleaned[0])]
    for start, end in cleaned[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return [tuple(iv) for iv in merged]
```

