def delays(attempts, base, cap):
    if not isinstance(attempts, int) or attempts < 1:
        raise ValueError("attempts must be an integer >= 1")
    if not isinstance(base, int) or base < 0:
        raise ValueError("base must be an integer >= 0")
    if not isinstance(cap, int) or cap < 0:
        raise ValueError("cap must be an integer >= 0")
    return [min(base * (2 ** i), cap) for i in range(attempts - 1)]
