def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries into a deep-independent result.

    - Overlay values replace base values (including lists and None).
    - A None value in overlay does not delete the key from the result.
    - Neither input is mutated, and the result shares no nested objects with either input.
    """
    result = {}
    for key in base:
        if key in overlay:
            b_val = base[key]
            o_val = overlay[key]
            if isinstance(b_val, dict) and isinstance(o_val, dict):
                result[key] = merge(b_val, o_val)
            else:
                result[key] = _deep_copy(o_val)
        else:
            result[key] = _deep_copy(base[key])
    for key in overlay:
        if key not in base:
            result[key] = _deep_copy(overlay[key])
    return result


def _deep_copy(val):
    """Return a deep copy of a JSON-like value (dict, list, or immutable scalar)."""
    if isinstance(val, dict):
        return {k: _deep_copy(v) for k, v in val.items()}
    if isinstance(val, list):
        return [_deep_copy(item) for item in val]
    return val
```

