def normalize(path):
    """Normalize an absolute POSIX-like path.

    - Raises ValueError if path is not absolute (doesn't start with '/').
    - Collapses repeated slashes.
    - Ignores '.' components.
    - Resolves '..' components without going above root.
    - Returns '/' for the root path.
    - Never returns a trailing slash (except for root).
    """
    if not isinstance(path, str) or not path.startswith('/'):
        raise ValueError(f"not an absolute path: {path!r}")

    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
```

