def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")
    if not items:
        return []

    result = []
    current = []
    current_bytes = 0

    for item in items:
        item_bytes = len(item.encode("utf-8"))
        if item_bytes > max_bytes:
            raise ValueError(f"item {item!r} does not fit in {max_bytes} bytes")
        if current_bytes + item_bytes <= max_bytes:
            current.append(item)
            current_bytes += item_bytes
        else:
            result.append(current)
            current = [item]
            current_bytes = item_bytes

    if current:
        result.append(current)

    return result
```

