import heapq


def order(deps):
    # Collect all nodes (keys + all prerequisite mentions)
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        all_nodes.update(prereqs)

    # Build per-node prerequisite sets without mutating deps
    prereqs = {node: set(deps.get(node, [])) for node in all_nodes}

    # Reverse adjacency: node -> list of nodes that depend on it
    dependents = {node: [] for node in all_nodes}
    for node in all_nodes:
        for p in prereqs[node]:
            dependents[p].append(node)

    # Seed heap with nodes that have no prerequisites
    ready = [node for node in all_nodes if not prereqs[node]]
    heapq.heapify(ready)

    result = []
    while ready:
        node = heapq.heappop(ready)
        result.append(node)
        for dep in dependents[node]:
            prereqs[dep].discard(node)
            if not prereqs[dep]:
                heapq.heappush(ready, dep)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
```

